ce":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":false}],"internal_job_id":3566649,"location":{"name":"Bengaluru, India"},"metadata":[{"id":58735330,"name":"Naukri Job URL","value":null,"value_type":"long_text"},{"id":58735350,"name":"Naukri Job Error","value":null,"value_type":"long_text"},{"id":58735367,"name":"Minimum Salary","value":null,"value_type":"number"},{"id":58735368,"name":"Maximum Salary","value":null,"value_type":"number"},{"id":58735369,"name":"Minimum Work Experience","value":null,"value_type":"number"},{"id":58735370,"name":"Maximum Work Experience","value":null,"value_type":"number"},{"id":58735384,"name":"City","value":null,"value_type":"single_select"},{"id":58735385,"name":"Job Description","value":null,"value_type":"long_text"}],"id":8242984,"updated_at":"2026-10-01T01:47:26-04:00","requisition_id":"P25721_3566649","title":"Senior Site Reliability Engineer","company_name":"Okta","first_published":"2026-10-01T01:47:26-04:00","language":"en","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Secure Every Identity, from AI to Human&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Identity is the key to unlocking the potential of AI. Okta secures AI by building the trusted, neutral infrastructure that enables organizations to safely embrace this new era. This work requires a relentless drive to solve complex challenges with real-world stakes. We are looking for builders and owners who operate with speed and urgency and execute with excellence.&lt;br&gt;&lt;br&gt;This is an opportunity to do career-defining work. We&#39;re all in on this mission. If you are too, let&#39;s talk.&lt;/p&gt;&lt;/div&gt;&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;The Engineering Opportunity&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;We are looking for an experienced Senior Site Reliability Engineer to join Okta&#39;s Emerging Products Group (EPG). Our mission is to build highly reliable, scalable, and secure cloud services that our customers can trust. We embrace an automation-first mindset and continuously invest in platform engineering, observability, and operational excellence to enable our engineering teams to move quickly and safely.&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;This role is ideal for an experienced Site Reliability Engineer who enjoys solving complex technical challenges at scale, building automation, and improving the reliability of production systems. You will serve as a key contributor within the EPG SRE organization, partnering closely with software engineers, architects, and product teams to design, build, and operate world-class cloud services.&lt;/p&gt;
&lt;p class=&quot;p2&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;What You&#39;ll Be Doing&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Reliability &amp;amp; Operations&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li1&quot;&gt;Design, build, and operate large-scale cloud infrastructure and production services.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Participate in an on-call rotation supporting highly available customer-facing systems.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Lead incident response efforts and drive post-incident reviews focused on systemic improvements.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Define, measure, and improve Service Level Indicators (SLIs), Service Level Objectives (SLOs), and error budgets.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Partner with engineering teams to improve service availability, scalability, performance, and resilience.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Continuously improve observability through metrics, logging, tracing, dashboards, and alerting.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Engineering &amp;amp; Automation&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li1&quot;&gt;Develop software, automation, and infrastructure using Go, Python, Terraform, and related technologies.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Eliminate operational toil through automation, tooling, and platform engineering.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Improve deployment safety and operational workflows through CI/CD and GitOps practices.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Collaborate on modernizing existing workloads and aligning them with evolving platform capabilities.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Build self-service platforms, operational guardrails, and automation that improve developer velocity while maintaining reliability and security.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;What We Are Looking For&lt;/strong&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Technical Excellence&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li1&quot;&gt;Strong experience operating large-scale production services in AWS and/or GCP.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Deep expertise with Kubernetes in production environments.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience troubleshooting Kubernetes networking, storage, scheduling, scaling, and workload lifecycle issues.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Extensive experience with Infrastructure as Code technologies such as Terraform and Helm.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Strong software engineering skills in Golang and/or Python.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience building automation and internal engineering platforms.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience operating and troubleshooting distributed data platforms such as PostgreSQL, Redis, OpenSearch, MySQL, Cassandra, or similar technologies.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Strong understanding of cloud networking fundamentals including DNS, load balancing, ingress, TLS, service networking, and traffic management.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience with observability platforms, monitoring strategies, and production telemetry.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience with or strong interest in AI-assisted engineering and operational automation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Operational Excellence&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ul1&quot;&gt;
&lt;li class=&quot;li1&quot;&gt;Strong expertise operating customer-facing production systems.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Experience leading incident response and driving operational improvements.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Deep understanding of reliability engineering concepts including SLIs, SLOs, error budgets, and capacity planning.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Strong understanding of CI/CD pipelines, deployment strategies, and automation-first operational practices.&lt;/li&gt;
&lt;li class=&quot;li1&quot;&gt;Proven ability to balance reliability, scalability, security, and engineering velocity.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;p2&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
