n":"San Francisco, CA, United States","child_ids":[],"parent_id":67252}],"ai_disclaimer":null,"include_ai_disclaimer":null,"ai_opt_out_request_url":null},{"absolute_url":"https://www.okta.com/company/careers/opportunity/7658254?gh_jid=7658254","data_compliance":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":false}],"internal_job_id":3372199,"location":{"name":"Bellevue, Washington; Chicago, Illinois; New York, New York; San Francisco, California; Washington, DC"},"metadata":[{"id":58735330,"name":"Naukri Job URL","value":null,"value_type":"long_text"},{"id":58735350,"name":"Naukri Job Error","value":null,"value_type":"long_text"},{"id":58735367,"name":"Minimum Salary","value":null,"value_type":"number"},{"id":58735368,"name":"Maximum Salary","value":null,"value_type":"number"},{"id":58735369,"name":"Minimum Work Experience","value":null,"value_type":"number"},{"id":58735370,"name":"Maximum Work Experience","value":null,"value_type":"number"},{"id":58735384,"name":"City","value":null,"value_type":"single_select"},{"id":58735385,"name":"Job Description","value":null,"value_type":"long_text"}],"id":7658254,"updated_at":"2026-10-26T19:49:19-04:00","requisition_id":"P14596_3372199","title":"Splunk Infrastructure Engineer ","company_name":"Okta","first_published":"2026-02-26T18:13:10-05:00","language":"en","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Secure Every Identity, from AI to Human&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Identity is the key to unlocking the potential of AI. Okta secures AI by building the trusted, neutral infrastructure that enables organizations to safely embrace this new era. This work requires a relentless drive to solve complex challenges with real-world stakes. We are looking for builders and owners who operate with speed and urgency and execute with excellence.&lt;br&gt;&lt;br&gt;This is an opportunity to do career-defining work. We&#39;re all in on this mission. If you are too, let&#39;s talk.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;SingleJob-content&quot;&gt;
&lt;h3&gt;&lt;strong&gt;Position Overview:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;We are seeking a highly technical &lt;strong&gt;Splunk Infrastructure&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;Engineer&lt;/strong&gt; with a specialty in Splunk to own and evolve our Splunk ecosystem. In this role, you will move beyond simple monitoring to delivering a world class, comprehensive, scalable Observability Platform that enables our SRE teams and business partners.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Splunk Engineering: Optimize the collection, processing, and storage of log data to ensure high reliability and low latency of our Splunk services&lt;/li&gt;
&lt;li&gt;Incident Response: Participate in on-call rotations and lead post-incident reviews to drive systemic improvements and &quot;observability-driven development.&quot;&lt;/li&gt;
&lt;li&gt;Automation: Eliminate &quot;toil&quot; by automating the deployment and scaling of observability agents and collectors.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Required Skills &amp;amp; Experience (The Essentials)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Log Management: Minimum 5+ Experience scaling and managing Splunk Cloud at scale (1000+ SVCs), including Workload Management (WLM) and HEC optimization. &lt;/strong&gt;&lt;strong&gt;Visualization: Expertise in creating intuitive, actionable Splunk dashboards that correlate data across multiple sources.&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Problem Solving:&lt;/strong&gt; A data-driven approach to debugging complex, cross-service performance bottlenecks.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Skills (The &quot;Nice-to-Haves&quot;)&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Telemetry Standards: &lt;/strong&gt;Hands-on experience with OpenTelemetry (OTel), Vector, or similar frameworks for instrumenting applications.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Charge-back app:&lt;/strong&gt; Experience in implementing Splunk charge-back app for usage reporting&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Cloud Platforms:&lt;/strong&gt; Experience managing observability native tools within AWS or GCP.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Additional requirements:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;This position requires the ability to access federal environments and/or have access to protected federal data.&amp;nbsp; As a condition of employment for this position, the successful candidate must be able to submit documentation establishing U.S. Person status (e.g. a U.S. Citizen, National, Lawful Permanent Resident, Refugee, or Asylee. 22 CFR 120.15) upon hire.&lt;/li&gt;
&lt;li&gt;This person must attend in person onboarding in our San Francisco/Chicago office the first week of employment.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
