data_compliance":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":false}],"internal_job_id":3500962,"location":{"name":"Bengaluru, India"},"metadata":[{"id":58735330,"name":"Naukri Job URL","value":null,"value_type":"long_text"},{"id":58735350,"name":"Naukri Job Error","value":null,"value_type":"long_text"},{"id":58735367,"name":"Minimum Salary","value":null,"value_type":"number"},{"id":58735368,"name":"Maximum Salary","value":null,"value_type":"number"},{"id":58735369,"name":"Minimum Work Experience","value":null,"value_type":"number"},{"id":58735370,"name":"Maximum Work Experience","value":null,"value_type":"number"},{"id":58735384,"name":"City","value":null,"value_type":"single_select"},{"id":58735385,"name":"Job Description","value":null,"value_type":"long_text"}],"id":8081016,"updated_at":"2026-09-21T12:43:00-04:00","requisition_id":"P24491_3500962","title":"Staff Software Engineer ","company_name":"Okta","first_published":"2026-08-13T00:42:14-04:00","language":"en","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Secure Every Identity, from AI to Human&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Identity is the key to unlocking the potential of AI. Okta secures AI by building the trusted, neutral infrastructure that enables organizations to safely embrace this new era. This work requires a relentless drive to solve complex challenges with real-world stakes. We are looking for builders and owners who operate with speed and urgency and execute with excellence.&lt;br&gt;&lt;br&gt;This is an opportunity to do career-defining work. We&#39;re all in on this mission. If you are too, let&#39;s talk.&lt;/p&gt;&lt;/div&gt;&lt;p data-renderer-start-pos=&quot;2559&quot; data-local-id=&quot;a69923d2aa9d&quot;&gt;We are seeking an experienced and technically influential &lt;strong data-renderer-mark=&quot;true&quot;&gt;Senior Software Development Engineer&lt;/strong&gt; to join our Cloud Tooling and Pipelines team. This pivotal team is responsible for the &lt;strong data-renderer-mark=&quot;true&quot;&gt;design, development, and maintenance&lt;/strong&gt; of our core &lt;strong data-renderer-mark=&quot;true&quot;&gt;Continuous Delivery (CD) platform&lt;/strong&gt; (leveraging Spinnaker and custom tooling), &lt;strong data-renderer-mark=&quot;true&quot;&gt;Infrastructure as Code (IaC) execution engines&lt;/strong&gt; (primarily Terraform), and a suite of supporting microservices. These systems are critical for enabling and managing our extensive resource footprint across AWS &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;ECS&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_1mT5xdRAKS&quot;&gt;&lt;span class=&quot;_0nmozVaHVx _2V7sgO2M4S _3BoeIDwZ7G _30zrXRyxdf _0ReiIH7zJH&quot; data-testid=&quot;definition-highlighter&quot;&gt;EKS&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;3089&quot; data-local-id=&quot;a456d8fce8af&quot;&gt;As a Senior Software Development Engineer, you will be a key contributor, driving the implementation of scalable, reliable, and secure software solutions that automate infrastructure provisioning and application deployments. Your deep expertise in &lt;strong data-renderer-mark=&quot;true&quot;&gt;software engineering principles&lt;/strong&gt; and cloud-native development will be essential in building and enhancing our critical tooling for infrastructure provisioning, vulnerability management, and IaC deployments. You will also play a vital role in mentoring other engineers and influencing the team&#39;s technical roadmap. If you have a strong passion for building robust software systems that empower operational efficiency at scale, we encourage you to apply.&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&quot;Key-Responsibilities&quot; data-local-id=&quot;1f43ff5ed949&quot; data-renderer-start-pos=&quot;3791&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Key Responsibilities&lt;/strong&gt;&lt;/h3&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;9ba43f1d-51c5-47a2-84a1-893870a7f5a8&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;3815&quot; data-local-id=&quot;8de3233c148e&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Design and Develop Core Platform Components:&lt;/strong&gt; Lead the design and development of scalable and reliable microservices and tools that form the backbone of Okta&#39;s Continuous Delivery (CD) platform (including components for Spinnaker, Terraform, and custom tooling).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4080&quot; data-local-id=&quot;a3d523e7d3b0&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Build Infrastructure as Code Automation:&lt;/strong&gt; Develop sophisticated software solutions and APIs that empower engineering teams to provision and manage infrastructure, execute production changes, and deploy code with high reliability and efficiency.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4327&quot; data-local-id=&quot;a09aa61d86d8&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Architect and Implement Deployment Workflows:&lt;/strong&gt; Contribute to the architectural design and hands-on implementation of robust CD pipelines and Terraform-based IaC workflows, ensuring scalability, reliability, and security for application deployments.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4578&quot; data-local-id=&quot;af3f3d797842&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Develop High-Quality Automation Software:&lt;/strong&gt; Write clean, efficient, and well-tested code (primarily in &lt;strong data-renderer-mark=&quot;true&quot;&gt;Java, Python, or Go&lt;/strong&gt;) for microservices with a strong focus on automation, operational excellence, and self-service capabilities.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;4811&quot; data-local-id=&quot;732e8c046ffa&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Collaborate for Operational Efficiency:&lt;/strong&gt; Partner closely with DevOps, SREs, and Product teams to proactively identify operational bottlenecks and manual processes. Then lead software development efforts to deliver scalable, reliable automation solutions.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;5068&quot; data-local-id=&quot;025e7a6a7892&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Champion Software Engineering Best Practices:&lt;/strong&gt; Advocate for and implement industry best practices in software design, development, testing, and deployment to ensure the highest quality and maintainability of our tooling.&lt;/p&gt;
