"data_compliance":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":false}],"internal_job_id":3485696,"location":{"name":"Tel Aviv, Israel"},"metadata":[{"id":58735330,"name":"Naukri Job URL","value":null,"value_type":"long_text"},{"id":58735350,"name":"Naukri Job Error","value":null,"value_type":"long_text"},{"id":58735367,"name":"Minimum Salary","value":null,"value_type":"number"},{"id":58735368,"name":"Maximum Salary","value":null,"value_type":"number"},{"id":58735369,"name":"Minimum Work Experience","value":null,"value_type":"number"},{"id":58735370,"name":"Maximum Work Experience","value":null,"value_type":"number"},{"id":58735384,"name":"City","value":null,"value_type":"single_select"},{"id":58735385,"name":"Job Description","value":null,"value_type":"long_text"}],"id":8041857,"updated_at":"2026-09-21T12:43:00-04:00","requisition_id":"P21523_3485696","title":"Staff Software Engineer ","company_name":"Okta","first_published":"2026-07-15T13:48:59-04:00","language":"en","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Secure Every Identity, from AI to Human&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Identity is the key to unlocking the potential of AI. Okta secures AI by building the trusted, neutral infrastructure that enables organizations to safely embrace this new era. This work requires a relentless drive to solve complex challenges with real-world stakes. We are looking for builders and owners who operate with speed and urgency and execute with excellence.&lt;br&gt;&lt;br&gt;This is an opportunity to do career-defining work. We&#39;re all in on this mission. If you are too, let&#39;s talk.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;strong&gt;The Identity Security Posture Management (ISPM) Team&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;At ISPM (formerly Spera Security), we are revolutionizing identity security for modern organizations. Our platform provides security leaders with end-to-end contextual visibility into their identity landscape—reducing risk, enhancing operational efficiency, and ensuring continuous compliance.&lt;/p&gt;
&lt;p&gt;We’re a fast-moving, high-impact team looking for an exceptional &lt;strong&gt;Staff Software Engineer&lt;/strong&gt; to help shape the future of identity security and platform architecture.&lt;/p&gt;
&lt;p&gt;Hybrid work - 3 days a week from the office.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;What You’ll Be Doing&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;As a Staff Software Engineer, you will serve as a technical authority and play a pivotal role in scaling our core platform. Your focus will span architecture, security research, and engineering excellence:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Lead &amp;amp; Architect:&lt;/strong&gt; Design, build, and scale high-performance software while driving architectural best practices across the R&amp;amp;D organization.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Security &amp;amp; AI Innovation:&lt;/strong&gt; Drive deep-dive research into cloud, SaaS ecosystems, and AI agents to build proactive detection models, mitigation strategies, and threat intelligence.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Engineering Excellence:&lt;/strong&gt; Elevate code quality, testing standards, system monitoring, and documentation across teams.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Cross-Functional Ownership:&lt;/strong&gt; Partner closely with Product and R&amp;amp;D to translate complex security requirements into scalable technical solutions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Scale &amp;amp; Optimize:&lt;/strong&gt; Identify and resolve systemic performance bottlenecks and architectural challenges.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Mentorship &amp;amp; Leadership:&lt;/strong&gt; Act as a technical mentor, driving engineering standards and fostering a strong knowledge-sharing culture.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;What You’ll Bring to the Role&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;7+ years&lt;/strong&gt; of software engineering experience, ideally in fast-paced, high-growth environments.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Cybersecurity Domain Expertise:&lt;/strong&gt; Hands-on experience in security product development, security research, or threat/incident response.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;4+ years&lt;/strong&gt; of hands-on experience with &lt;strong&gt;Python&lt;/strong&gt;, focusing on backend architecture and scalable systems.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Proven System Ownership:&lt;/strong&gt; A track record of designing, building, and operating large-scale, complex distributed systems.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strong CS Fundamentals:&lt;/strong&gt; Deep understanding of software design patterns, system architecture, and technical leadership.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Communication &amp;amp; Influence:&lt;/strong&gt; Excellent problem-solving skills with the ability to communicate complex technical concepts clearly across teams.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;Extra Credit&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Experience with &lt;strong&gt;Snowflake&lt;/strong&gt; or other modern data warehousing platforms.&lt;/li&gt;
&lt;li&gt;Hands-on experience with &lt;strong&gt;AWS&lt;/strong&gt; and modern cloud-native architectures.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;
