ata_compliance":[{"type":"gdpr","requires_consent":false,"requires_processing_consent":false,"requires_retention_consent":false,"retention_period":null,"demographic_data_consent_applies":false}],"internal_job_id":3101360,"location":{"name":"Mexico City, Mexico"},"metadata":[{"id":58735330,"name":"Naukri Job URL","value":null,"value_type":"long_text"},{"id":58735350,"name":"Naukri Job Error","value":null,"value_type":"long_text"},{"id":58735367,"name":"Minimum Salary","value":null,"value_type":"number"},{"id":58735368,"name":"Maximum Salary","value":null,"value_type":"number"},{"id":58735369,"name":"Minimum Work Experience","value":null,"value_type":"number"},{"id":58735370,"name":"Maximum Work Experience","value":null,"value_type":"number"},{"id":58735384,"name":"City","value":null,"value_type":"single_select"},{"id":58735385,"name":"Job Description","value":null,"value_type":"long_text"}],"id":6725699,"updated_at":"2026-09-21T12:43:00-04:00","requisition_id":"P7997_3101360","title":"Technical Support Engineer","company_name":"Okta","first_published":"2025-04-04T14:53:43-04:00","language":"en","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Secure Every Identity, from AI to Human&lt;br&gt;&lt;br&gt;&lt;/strong&gt;Identity is the key to unlocking the potential of AI. Okta secures AI by building the trusted, neutral infrastructure that enables organizations to safely embrace this new era. This work requires a relentless drive to solve complex challenges with real-world stakes. We are looking for builders and owners who operate with speed and urgency and execute with excellence.&lt;br&gt;&lt;br&gt;This is an opportunity to do career-defining work. We&#39;re all in on this mission. If you are too, let&#39;s talk.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Position Description:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The ideal Technical Support Engineer is an articulate and seasoned technical specialist who understands and can appreciate the challenges organizations face in implementing and integrating cloud technologies into their existing on-premise or hosted user stores. You have technical depth and a customer-first mentality, the motivation to take the initiative to own and resolve customer issues, and an interest in working in a dynamic, fast-growing, learning environment.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Job Duties and Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;A Technical Support Engineer is the primary point of contact for all support related issues for Okta’s enterprise customers.&amp;nbsp; A TSE acts as the voice of the custom to ensure technical support and best practice guidance are provided within published SLAs.&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Take end-to-end ownership of customer issues, including initial troubleshooting, identification of root cause, and issue resolution.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Meet or exceed customer expectations on response quality, timeliness of responses, and overall customer experience.&lt;/li&gt;
&lt;li&gt;Provide well-thought-out and reliable direction, both in technical and non-technical terms, to help customers integrate, deploy, and maintain Okta’s suite of products.&lt;/li&gt;
&lt;li&gt;Serve as an internal and external point of contact on customer matters and ensure customer issues are resolved as expediently as possible.&lt;/li&gt;
&lt;li&gt;Collect information and document bugs with Engineering for product issues that are impacting customers.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Function as a subject matter expert within support for Okta’s suite of products&lt;/li&gt;
&lt;li&gt;Contribute to and maintain repository of knowledge within support and promote a culture of team knowledge share and collaboration within the directories product support group&lt;/li&gt;
&lt;li&gt;Stay up to date on emerging technologies, industry trends and best practices around the most common directory solutions and Okta’s interlock with them&lt;/li&gt;
&lt;li&gt;Push creative thinking beyond the boundaries of existing industry-standard practices to come up with process improvements and new ways to delight customers.&lt;/li&gt;
&lt;li&gt;Be a customer advocate for timely resolution of the problems reported, understand the environment/network and impact on business&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Required Skills:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of customer support, technical support, system administration, or related customer-facing role&lt;/li&gt;
&lt;li&gt;BA/BS/MS in Computer Science, Management Information Systems, or related discipline, or relevant professional experience.&lt;/li&gt;
&lt;li&gt;Familiarity with networking at OSI Model Layers 3-7, and troubleshooting through use of appropriate tools (HAR/Fiddler captures, Packet/Wireshark captures, Reviewing application logs, SIEM logs, etc.)&lt;/li&gt;
&lt;li&gt;Basic ability troubleshooting common protocols and services for cloud-based services (TCP/IP, DNS, TLS, certificates/PKI, HTTP servers, Web browsers, etc.)&lt;/li&gt;
&lt;li&gt;Familiarity with various Multi-factor authentication (MFA) technologies&lt;/li&gt;
&lt;li&gt;Familiarity with federation/SSO technologies and applications (SAML/WS-Fed, OIDC, and products like Okta, Ping Identity, ADFS, etc.)&lt;/li&gt;
&lt;li&gt;Familiarity with products and services used in a zero-trust modelled environment&lt;/li&gt;
&lt;li&gt;Experience working with RESTful services via APIs with appropriate tools (cURL, Postman, SoapUI or similar)&lt;/li&gt;
&lt;li&gt;Basic knowledge with Powershell/cmd, Bash, and common command-line tools&lt;/li&gt;
&lt;li&gt;Certifications such as Network+, Security+, Cisco CCNA, CISSP&lt;/li&gt;
&lt;li&gt;Experience with configuring enterprise applications in cloud and on-prem environments&lt;/li&gt;
&lt;li&gt;Experience with troubleshooting desktop applications across Windows, Mac OS, and Linux&lt;/li&gt;
&lt;li&gt;Familiarity with cloud based directory services (Okta Universal Directory, Azure Active Directory)&lt;/li&gt;
&lt;li&gt;Familiarity with Active Directory in on-premise environments&lt;/li&gt;
&lt;li&gt;Excellent relationship management, customer service, and communication skills in a variety of forms (written, live chat, conference calls, in-person.)&lt;/li&gt;
&lt;li&gt;Ability to work independently with little direct supervision and as a part of a team. Excellent analytical and organizational abilities. Ability to remain calm, composed, and articulate when dealing with tough customer situations.&lt;/li&gt;
&lt;li&gt;Ability to provide high quality notes and documentation when tracking work in a ticketing/case management system (Salesforce, Jira, Service-Now, etc.)&lt;/li&gt;
&lt;li&gt;Ability to provide high quality knowledge transfer, such as creating or updating knowledgebase articles, giving demonstrations, learning session presentations, etc.&lt;/li&gt;
&lt;li&gt;Experience translating customer issues into engineering centric reports via JIRA or other bug reporting systems&lt;/li&gt;
&lt;li&gt;Prior experience providing support to large enterprise customers preferably with customer management interaction.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Bonus Preferred:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Microsoft certifications related to Azure, Office 365, Windows, Windows Server&lt;/li&gt;
&lt;li&gt;Experience with setup, administration, and support of Office 365 in an enterprise environment with a focus on federation, and features like Autopilot, Windows Hello&lt;/li&gt;
&lt;li&gt;AWS/Google/Microsoft cloud certifications&lt;/li&gt;
&lt;/ul&gt;
